def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in my if x == 'C')
    my_d = n - my_c
    overall_ratio = opp_c / float(n)

    if opp_c == 0:
        return 'D'

    if n >= 5:
        d5 = 0
        for x in op[-5:]:
            if x == 'D':
                d5 += 1
        if d5 == 5 and opp_d * 5 >= n * 2 and overall_ratio < 0.80:
            return 'D'

    if n >= 10:
        recent = op[-10:]
        recent_len = 10
    else:
        recent = op
        recent_len = n

    recent_c = sum(1 for x in recent if x == 'C')
    recent_d = recent_len - recent_c
    recent_ratio = recent_c / float(recent_len)

    if recent_d >= 8 and overall_ratio < 0.85:
        return 'D'
    if recent_d >= 6 and overall_ratio < 0.55:
        return 'D'

    tC_c = 0
    tC_d = 0
    tD_c = 0
    tD_d = 0
    rC_c = 0
    rC_d = 0
    rD_c = 0
    rD_d = 0

    start = n - 16
    if start < 0:
        start = 0

    for i in range(n - 1):
        a = my[i]
        b = op[i + 1]
        in_recent = 1 if i >= start else 0
        if a == 'C':
            if b == 'C':
                tC_c += 1
                if in_recent:
                    rC_c += 1
            else:
                tC_d += 1
                if in_recent:
                    rC_d += 1
        else:
            if b == 'C':
                tD_c += 1
                if in_recent:
                    rD_c += 1
            else:
                tD_d += 1
                if in_recent:
                    rD_d += 1

    tC_total = tC_c + tC_d
    tD_total = tD_c + tD_d
    rC_total = rC_c + rC_d
    rD_total = rD_c + rD_d

    if rC_total >= 3:
        pC = (rC_c + 1.0) / (rC_total + 2.0)
    elif tC_total > 0:
        pC = (tC_c + 1.0) / (tC_total + 2.0)
    else:
        pC = recent_ratio

    if rD_total >= 2:
        pD = rD_c / (rD_total + 4.0)
    elif tD_total > 0:
        pD = tD_c / (tD_total + 4.0)
    else:
        pD = 0.02

    if pC < 0.0:
        pC = 0.0
    if pC > 1.0:
        pC = 1.0
    if pD < 0.0:
        pD = 0.0
    if pD > 1.0:
        pD = 1.0

    trans_now = pC if my[-1] == 'C' else pD
    p_now = 0.7 * trans_now + 0.3 * recent_ratio
    if p_now < 0.0:
        p_now = 0.0
    if p_now > 1.0:
        p_now = 1.0

    if rD_total >= 2:
        dsuc = rD_c
        dfail = rD_d
    else:
        dsuc = tD_c
        dfail = tD_d

    R = 100 - n
    vc = 0.0
    vd = 0.0

    for step in range(1, R):
        old_vc = vc
        old_vd = vd

        c_val = 3.0 * pC + old_vc
        d_val = 1.0 + 4.0 * pC + old_vd
        vc = c_val if c_val >= d_val else d_val

        c_val = 3.0 * pD + old_vc
        d_val = 1.0 + 4.0 * pD + old_vd
        vd = c_val if c_val >= d_val else d_val

    scoreC = 3.0 * p_now + vc
    scoreD = 1.0 + 4.0 * p_now + vd

    base_defect = scoreD >= scoreC + 0.25

    if not base_defect:
        mutual = (my[-1] == 'C' and op[-1] == 'C')

        if mutual and recent_ratio >= 0.85 and overall_ratio >= 0.80 and my_d <= max(2, n // 10):
            if dsuc == 0 and dfail == 0 and rng.random() < 0.05:
                return 'D'
            if dsuc == 0 and dfail <= 1 and rng.random() < 0.02:
                return 'D'

        if mutual and recent_ratio >= 0.70 and dsuc > dfail:
            adv = dsuc - dfail
            if dsuc == 1 and dfail == 0 and rng.random() < 0.30:
                return 'D'
            if dsuc == 2 and dfail == 0 and rng.random() < 0.55:
                return 'D'
            if dsuc == 3 and dfail == 0 and rng.random() < 0.75:
                return 'D'
            if dsuc >= 4 and dfail == 0:
                return 'D'
            if adv >= 2 and rng.random() < 0.40:
                return 'D'

        if n >= 90 and mutual and recent_ratio >= 0.90 and rng.random() < 0.10:
            return 'D'

    return 'D' if base_defect else 'C'
